### Tested versions

Godot 4.6

### System information

Linux mint xfce godot 4.6 compatability render

### Issue description

I'm making 3D racing vehicle car using characterbody3D with collision shape box fit whole car and floor as staticbody3D, but some times the car start vibrate suddenly like stack in the floor and force it self to pull out, i don't know how i can fix that bug

### Steps to reproduce

```gdscript
extends CharacterBody3D

# === CAR SETTINGS ===
@export var acceleration = 5.0
@export var max_speed = 25.0
@export var friction = 5.0
@export var steer_speed = 2.5
@export var gravity = 12.0
@export var wheel_radius = 0.5
@export var max_steer_angle = 30.0
@export var min_steer_factor = 0.5
@export var tilt_smoothness = 5.0

# === AUDIO ===
@onready var engine_audio = $EngineSound
@onready var skid_audio = $SkidSound
@export var smoke_scene: PackedScene

# === CHECKPOINT ===
var race_started: bool = false
var current_checkpoint: int = 0
var lap: int = 0
var total_checkpoints: int = 3

# === INTERNAL VARIABLES ===
var was_stopped = false
var vertical_velocity = 0.0
var speed = 0.0
var is_drifting: bool = false
var drift_timer: float = 0.0
var was_in_air: bool = false
var landing_timer: float = 0.0
var skid_timer: float = 0.0

# === NODES ===
@onready var fl_pivot: Node3D = $FlPivot
@onready var fr_pivot: Node3D = $FrPivot
@onready var blw: MeshInstance3D = $BLW
@onready var brw: MeshInstance3D = $BRW
@onready var flw: MeshInstance3D = $FlPivot/FLW
@onready var frw: MeshInstance3D = $FrPivot/FRW

func _ready() -> void:
	add_to_group("Car")
	safe_margin = 0.15
	floor_max_angle = 0.7
	floor_stop_on_slope = false
	motion_mode = CharacterBody3D.MOTION_MODE_GROUNDED

	# Audio setup
	if engine_audio:
		engine_audio.play()

func _physics_process(delta: float) -> void:

	# --- GRAVITY ---
	if not is_on_floor():
		vertical_velocity -= gravity * 0.8 * delta
		was_in_air = true
		landing_timer = 0.2
	else:
		if was_in_air:
			landing_timer -= delta
			if landing_timer <= 0:
				was_in_air = false
				vertical_velocity = 0
				velocity.y = 0.1
		else:
			vertical_velocity = 0.0

	# --- INPUTS ---
	var forward_input = Input.get_action_strength("ui_up") - Input.get_action_strength("ui_down")
	var steering_input = Input.get_action_strength("ui_left") - Input.get_action_strength("ui_right")

	# --- ACCELERATION / SPEED ---
	if forward_input != 0:
		speed += forward_input * acceleration * delta
	else:
		var friction_factor = clamp(speed / max_speed, 0.2, 1.0)
		speed = move_toward(speed, 0, friction * friction_factor * delta)

	speed = clamp(speed, -max_speed, max_speed)

	# --- HIGH-SPEED STEERING ---
	var speed_factor = clamp(abs(speed) / max_speed, 0.0, 1.0)
	var steering_factor = max(1.0 - speed_factor, min_steer_factor)
	var steering_amount = steer_speed * steering_factor

	# Check if car stopped
	if speed == 0 and abs(forward_input) == 0:
		if not was_stopped:
			velocity = Vector3.ZERO
			vertical_velocity = 0
			was_stopped = true
		return
	else:
		was_stopped = false

	# Rotate car body by input
	if speed != 0:
		rotate_y(steering_input * steering_amount * delta * sign(speed))

	# --- FRONT WHEEL VISUALS ---
	var front_steer_deg = steering_input * max_steer_angle * steering_factor
	var front_steer_rad = deg_to_rad(front_steer_deg)
	fl_pivot.rotation.y = front_steer_rad
	fr_pivot.rotation.y = front_steer_rad

	# --- WHEEL ROTATION ---
	var wheel_rot = speed / wheel_radius * delta
	flw.rotate_x(wheel_rot)
	frw.rotate_x(wheel_rot)
	blw.rotate_x(wheel_rot)
	brw.rotate_x(wheel_rot)

	# --- DRIFT DETECTION ---
	var braking = forward_input < 0
	var turning = abs(steering_input) > 0.5
	var speed_high = abs(speed) > 8.0

	is_drifting = braking and turning and speed_high

	if is_drifting:
		drift_timer = 0.2

	if drift_timer > 0:
		drift_timer -= delta

	# --- GRIP SETTINGS ---
	var front_grip = 6.0
	var rear_grip = 6.0

	if braking and turning:
		rear_grip = 1.5

	# --- VELOCITY CALCULATION ---
	var forward = transform.basis.z
	var right = transform.basis.x

	var forward_speed = forward.dot(velocity)
	var sideway_speed = right.dot(velocity)

	if is_on_floor():
		# Reduce grip during drift
		var grip_multiplier = 1.0
		if is_drifting or drift_timer > 0:
			grip_multiplier = 0.35

		# Reduce grip during landing
		if landing_timer > 0:
			grip_multiplier *= 0.5

		var forward_grip_strength = clamp(front_grip * delta * grip_multiplier, 0.0, 0.25)
		var side_grip_strength = clamp(rear_grip * delta * grip_multiplier, 0.0, 0.3)

		forward_speed = lerp(forward_speed, speed, forward_grip_strength)
		sideway_speed = lerp(sideway_speed, 0.0, side_grip_strength)

		velocity = forward * forward_speed + right * sideway_speed
		velocity.y = vertical_velocity
	else:
		velocity.y = vertical_velocity

	# --- SMOOTH SLOPE TILT ---
	if is_on_floor():
		var floor_normal = get_floor_normal()

		var car_forward = -transform.basis.z
		var car_right = transform.basis.x

		var forward_on_slope = car_forward - car_forward.dot(floor_normal) * floor_normal
		var right_on_slope = car_right - car_right.dot(floor_normal) * floor_normal

		forward_on_slope = forward_on_slope.normalized()
		right_on_slope = right_on_slope.normalized()

		var pitch_angle = asin(clamp(forward_on_slope.dot(Vector3.UP), -1.0, 1.0))
		var roll_angle = asin(clamp(right_on_slope.dot(Vector3.UP), -1.0, 1.0))

		var speed_factor_tilt = clamp(abs(speed) / max_speed, 0.0, 1.0)
		var damping = 1.0 - speed_factor_tilt * 0.7

		rotation.x = lerp(rotation.x, pitch_angle, tilt_smoothness * delta * damping)
		rotation.z = lerp(rotation.z, roll_angle, tilt_smoothness * delta * damping)
	else:
		rotation.x = lerp(rotation.x, 0.0, tilt_smoothness * delta)
		rotation.z = lerp(rotation.z, 0.0, tilt_smoothness * delta)

	# --- ENGINE SOUND ---
	if engine_audio:
		var target_pitch = lerp(0.7, 1.5, abs(speed) / max_speed)
		engine_audio.pitch_scale = target_pitch

		if speed == 0 and abs(forward_input) == 0:
			engine_audio.volume_db = lerp(engine_audio.volume_db, -80, 3.0 * delta)
		else:
			engine_audio.volume_db = lerp(engine_audio.volume_db, 0, 3.0 * delta)

	# --- SKID SOUND AND SMOKE ---
	if skid_audio:
		var should_skid = is_drifting or (braking and turning and abs(speed) > 5.0)

		if should_skid:
			if not skid_audio.playing:
				skid_audio.play()

			var intensity = clamp(abs(steering_input) + (abs(sideway_speed) / 10.0), 0.0, 1.0)
			skid_audio.volume_db = lerp(skid_audio.volume_db, lerp(-15.0, 0.0, intensity), 5.0 * delta)

			# Smoke
			skid_timer += delta
			if skid_timer >= 0.15 and smoke_scene:
				skid_timer = 0
				make_smoke()
		else:
			skid_audio.volume_db = lerp(skid_audio.volume_db, -80, 3.0 * delta)
			if skid_audio.volume_db <= -79:
				skid_audio.stop()
			skid_timer = 0

	# --- MOVE CAR ---
	move_and_slide()

	# Clean up micro-velocities
	if abs(speed) < 0.05 and abs(forward_input) < 0.05:
		velocity.x = 0
		velocity.z = 0

# --- SMOKE FUNCTION ---
func make_smoke():
	if not smoke_scene:
		return
	var tires = [blw, brw]
	for tire in tires:
		var smoke = smoke_scene.instantiate()
		var random_offset = Vector3(randf_range(-0.3, 0.3), randf_range(0, 0.2), randf_range(-0.3, 0.3))
		smoke.global_position = tire.global_position + random_offset
		get_tree().root.add_child(smoke)

		var tween = create_tween()
		tween.set_parallel(true)
		tween.tween_property(smoke, "scale", Vector3(1.5, 1.5, 1), 0.5)

		await get_tree().create_timer(0.6).timeout
		smoke.queue_free()

# --- CHECKPOINT FUNCTION ---
func passed_checkpoint(number: int, is_finish: bool):
	if not race_started:
		if number == 0:
			race_started = true
			current_checkpoint = 0
		return

	if not is_finish and number == current_checkpoint + 1:
		current_checkpoint = number
		return

	if is_finish and current_checkpoint == total_checkpoints - 1:
		lap += 1
		current_checkpoint = 0
		print("Lap:", lap)

